script.setup:
// differential-line — a port of Anders Hoff's (inconvergent) differential-line (MIT), Python/Cython → JS + WebGL2.
// A closed line of vertices: each is pulled toward its two neighbours, pushed away from every other vertex
// within farl, and edges split at random once they are longer than nearl, so the line grows and folds into
// brain-coral shapes. Ported from src/differentialLine.pyx (optimize_position, __reject), src/segments.pyx
// (split_edge, init_circle_segment), src/zonemap.pxd (the neighbour grid) and modules/growth.py (spawn),
// commit d951ed4; parameters from main_ani.py. Drawing (fading growth trails, filled interior, colour along
// the line) is this scene's own.
// with a counting sort, which is O(n) and cache-friendly.
function createLine(cap) {
  const L = {
    cap, n: 0,
    x: new Float64Array(cap), y: new Float64Array(cap),
    nx: new Int32Array(cap), pv: new Int32Array(cap),   // next / previous vertex along the closed line
    born: new Float32Array(cap),                         // step at which a vertex was born (for colour)
    sx: new Float64Array(cap), sy: new Float64Array(cap),
    cellOf: new Int32Array(cap), order: new Int32Array(cap),
    cellStart: new Int32Array(1), gw: 0, gh: 0,
    farl: 0.04, nearl: 0.002, stp: 0.0004,
    steps: 0,
  };
  return L;
}
// init_circle_segment: a closed ring of vertices at sorted random angles
function addRing(L, cx, cy, r, num) {
  const angles = Array.from({ length: num }, () => Math.random() * Math.PI * 2).sort((a, b) => a - b);
  const first = L.n;
  if (L.n + num > L.cap) return;
  for (let k = 0; k < num; k++) {
    const i = L.n++;
    L.x[i] = cx + Math.cos(angles[k]) * r; L.y[i] = cy + Math.sin(angles[k]) * r;
    L.nx[i] = k === num - 1 ? first : i + 1;
    L.pv[i] = k === 0 ? first + num - 1 : i - 1;
    L.born[i] = L.steps;
  }
}
// One optimize_position step: every vertex is pulled toward its two neighbours when further than nearl
// and pushed away from every other vertex closer than farl, by (farl/d - 1) * d * step.
function optimize(L, x0, y0, w, h) {
  const { n, x, y, nx, pv, sx, sy, farl, nearl, stp } = L;
  const gw = Math.max(1, Math.ceil(w / farl)), gh = Math.max(1, Math.ceil(h / farl)), cells = gw * gh;
  if (L.cellStart.length < cells + 1) L.cellStart = new Int32Array(cells + 1);
  const start = L.cellStart, cellOf = L.cellOf, order = L.order;
  start.fill(0, 0, cells + 1);
  for (let i = 0; i < n; i++) {
    let cx = Math.floor((x[i] - x0) / farl), cy = Math.floor((y[i] - y0) / farl);
    cx = cx < 0 ? 0 : cx >= gw ? gw - 1 : cx; cy = cy < 0 ? 0 : cy >= gh ? gh - 1 : cy;
    const c = cx + cy * gw; cellOf[i] = c; start[c + 1]++;
  }
  for (let c = 0; c < cells; c++) start[c + 1] += start[c];
  // fill order (use sx as a temporary write cursor would cost a copy; a second pass with a cursor array)
  const cur = L.cur && L.cur.length >= cells ? L.cur : (L.cur = new Int32Array(cells));
  cur.set(start.subarray(0, cells));
  for (let i = 0; i < n; i++) order[cur[cellOf[i]]++] = i;
  const farl2 = farl * farl;
  for (let v = 0; v < n; v++) {
    const xv = x[v], yv = y[v], v1 = nx[v], v2 = pv[v];
    let rx = 0, ry = 0;
    const c = cellOf[v], cx = c % gw, cy = (c - cx) / gw;
    const ax = cx > 0 ? cx - 1 : 0, bx = cx < gw - 1 ? cx + 1 : cx;
    const ay = cy > 0 ? cy - 1 : 0, by = cy < gh - 1 ? cy + 1 : cy;
    for (let gy = ay; gy <= by; gy++) {
      const row = gy * gw;
      for (let k = start[row + ax], e = start[row + bx + 1]; k < e; k++) {
        const j = order[k];
        if (j === v || j === v1 || j === v2) continue;
        const dx = xv - x[j], dy = yv - y[j], d2 = dx * dx + dy * dy;
        if (d2 > farl2 || d2 <= 0) continue;
        const f = (farl / Math.sqrt(d2) - 1) * stp;
        rx += dx * f; ry += dy * f;
      }
    }
    // linked neighbours: attract when further than nearl
    for (const j of [v1, v2]) {
      const dx = xv - x[j], dy = yv - y[j], d = Math.sqrt(dx * dx + dy * dy);
      if (d < nearl || d <= 0) continue;
      rx -= (dx / d) * stp; ry -= (dy / d) * stp;
    }
    sx[v] = rx; sy[v] = ry;
  }
  for (let v = 0; v < n; v++) { x[v] += sx[v]; y[v] += sy[v]; }
  L.steps++;
}
// spawn(df, nearl, limit): each edge (v, next v) is split at its midpoint with probability `limit`
// when it is at least nearl long.
function spawn(L, limit) {
  const n0 = L.n, { x, y, nx, pv } = L;
  const nearl2 = L.nearl * L.nearl;
  for (let v = 0; v < n0 && L.n < L.cap; v++) {
    if (Math.random() >= limit) continue;
    const w = nx[v], dx = x[w] - x[v], dy = y[w] - y[v];
    if (dx * dx + dy * dy < nearl2) continue;
    const m = L.n++;
    x[m] = (x[v] + x[w]) * 0.5; y[m] = (y[v] + y[w]) * 0.5;
    nx[v] = m; pv[m] = v; nx[m] = w; pv[w] = m;
    L.born[m] = L.steps;
  }
}

// --- drawing ------------------------------------------------------------------------------------------------
const gl = ctx.gl, s = ctx.state;
const floatOK = !!gl.getExtension("EXT_color_buffer_float");
// Segments as instanced quads: per instance (x1, y1, x2, y2, t), t = position along the ring for colour.
const segVs = `#version 300 es
precision highp float;
layout(location=0) in vec4 a_seg;
layout(location=1) in float a_t;
uniform vec2 u_resolution, u_center;
uniform float u_unit, u_lw;
out float v_t;
out float v_side;
void main() {
  vec2 a = u_center + a_seg.xy * u_unit, b = u_center + a_seg.zw * u_unit;
  vec2 d = b - a; float len = length(d);
  vec2 dir = len > 1e-5 ? d / len : vec2(1.0, 0.0), nrm = vec2(-dir.y, dir.x);
  int id = gl_VertexID;                 // two triangles: (0,1,2) (2,1,3)
  int c = id < 3 ? id : (id == 3 ? 2 : (id == 4 ? 1 : 3));
  float along = (c & 1) == 0 ? 0.0 : 1.0, side = c < 2 ? -1.0 : 1.0;
  float hw = u_lw * 0.5 + 0.5;
  vec2 p = mix(a - dir * hw * 0.5, b + dir * hw * 0.5, along) + nrm * side * hw;
  v_t = a_t; v_side = side * hw;
  gl_Position = vec4(p / u_resolution * 2.0 - 1.0, 0.0, 1.0);
}`;
const PAL = `
uniform vec3 u_pa, u_pb, u_pc, u_pd;
vec3 pal(float t) { return clamp(u_pa + u_pb * cos(6.28318 * (u_pc * t + u_pd)), 0.0, 1.0); }`;
const segFs = `#version 300 es
precision highp float;
in float v_t; in float v_side;
uniform float u_lw, u_alpha, u_mix;
uniform vec3 u_solid;
out vec4 outColor;
${PAL}
void main() {
  float cov = clamp(u_lw * 0.5 + 0.5 - abs(v_side), 0.0, 1.0);
  vec3 col = mix(pal(v_t), u_solid, u_mix);
  float a = cov * u_alpha;
  outColor = vec4(col * a, a);
}`;
// Signed triangle fans: inside a closed ring they sum to ±1, outside they cancel.
const fanVs = `#version 300 es
precision highp float;
layout(location=0) in vec3 a_p;
uniform vec2 u_resolution, u_center;
uniform float u_unit;
out float v_s;
void main() { v_s = a_p.z; gl_Position = vec4((u_center + a_p.xy * u_unit) / u_resolution * 2.0 - 1.0, 0.0, 1.0); }`;
const fanFs = `#version 300 es
precision highp float;
in float v_s; out vec4 outColor;
void main() { outColor = vec4(v_s, 0.0, 0.0, 0.0); }`;
const viewFs = `#version 300 es
precision highp float;
in vec2 v_uv; out vec4 outColor;
uniform sampler2D u_trailTex, u_fillTex;
uniform vec2 u_resolution;
uniform float u_dark, u_fillAmt, u_trailAmt;
uniform vec3 u_ground;
${PAL}
float h(vec2 p) { return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453); }
void main() {
  vec4 tr = texture(u_trailTex, v_uv) * u_trailAmt;
  float inside = clamp(abs(texture(u_fillTex, v_uv).r), 0.0, 1.0);
  vec2 q = (v_uv - 0.5) * vec2(u_resolution.x / u_resolution.y, 1.0);
  float vig = 1.0 - 0.3 * dot(q, q);
  vec3 tint = pal(0.15 + 0.5 * v_uv.y);
  float n = (h(gl_FragCoord.xy) - 0.5) * 0.02;
  vec3 light = u_ground * vig;
  light = mix(light, light * mix(vec3(1.0), tint, 0.45), inside * u_fillAmt);
  light *= exp(-1.6 * max(tr.a - tr.rgb, vec3(0.0)));
  vec3 dark = u_ground * vig + tint * 0.22 * inside * u_fillAmt;
  dark += (1.0 - exp(-1.4 * tr.rgb));
  outColor = vec4(mix(light, dark, u_dark) + n, 1.0);
}`;
const fadeFs = `#version 300 es
precision highp float;
in vec2 v_uv; out vec4 outColor;
uniform float u_keep;
void main() { outColor = vec4(u_keep); }`;
s.segProg = ctx.utils.createProgram(segVs, segFs);
s.fanProg = ctx.utils.createProgram(fanVs, fanFs);
s.viewProg = ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER, viewFs);
s.fadeProg = ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER, fadeFs);
s.floatOK = floatOK;

const CAP = 40000;
s.L = createLine(CAP);
s.segData = new Float32Array(CAP * 5);
s.fanData = new Float32Array(CAP * 9);
s.segBuf = gl.createBuffer(); s.fanBuf = gl.createBuffer();
gl.bindBuffer(gl.ARRAY_BUFFER, s.segBuf); gl.bufferData(gl.ARRAY_BUFFER, s.segData.byteLength, gl.DYNAMIC_DRAW);
gl.bindBuffer(gl.ARRAY_BUFFER, s.fanBuf); gl.bufferData(gl.ARRAY_BUFFER, s.fanData.byteLength, gl.DYNAMIC_DRAW);
s.segVao = gl.createVertexArray();
gl.bindVertexArray(s.segVao); gl.bindBuffer(gl.ARRAY_BUFFER, s.segBuf);
gl.enableVertexAttribArray(0); gl.vertexAttribPointer(0, 4, gl.FLOAT, false, 20, 0); gl.vertexAttribDivisor(0, 1);
gl.enableVertexAttribArray(1); gl.vertexAttribPointer(1, 1, gl.FLOAT, false, 20, 16); gl.vertexAttribDivisor(1, 1);
s.fanVao = gl.createVertexArray();
gl.bindVertexArray(s.fanVao); gl.bindBuffer(gl.ARRAY_BUFFER, s.fanBuf);
gl.enableVertexAttribArray(0); gl.vertexAttribPointer(0, 3, gl.FLOAT, false, 12, 0);
gl.bindVertexArray(null);
s.visited = new Uint8Array(CAP);

// cosine palettes (a + b cos 2π(c t + d)), with ground colour and the colour of the live line
s.palettes = [
  { name: "Coral reef", dark: 1, ground: [0.03, 0.045, 0.07], a: [0.65, 0.5, 0.45], b: [0.35, 0.35, 0.3], c: [1, 1, 1], d: [0.0, 0.12, 0.3], solid: [1, 0.96, 0.9], mix: 0.35 },
  { name: "Ink", dark: 0, ground: [0.95, 0.93, 0.88], a: [0.25, 0.28, 0.35], b: [0.2, 0.2, 0.2], c: [1, 1, 1], d: [0.0, 0.1, 0.2], solid: [0.04, 0.05, 0.08], mix: 0.85 },
  { name: "Aurora", dark: 1, ground: [0.02, 0.03, 0.05], a: [0.4, 0.65, 0.6], b: [0.4, 0.35, 0.4], c: [1, 1, 1], d: [0.55, 0.25, 0.0], solid: [0.85, 1, 0.95], mix: 0.3 },
  { name: "Tide", dark: 0, ground: [0.94, 0.92, 0.86], a: [0.35, 0.35, 0.5], b: [0.35, 0.3, 0.25], c: [1, 1, 1], d: [0.5, 0.6, 0.7], solid: [0.1, 0.12, 0.3], mix: 0.5 },
];
s.run = -1;
s.wasDown = false;
s.fadeT = 1;
s.sim = { addRing, optimize, spawn };

script.render:
const { addRing, optimize, spawn } = ctx.state.sim;
const s = ctx.state, gl = ctx.gl, u = ctx.uniforms, L = s.L, [w, h] = ctx.resolution;
const S = Math.min(w, h);
// The simulation keeps the original's units (farl 0.04); Fold size sets how much of the screen one farl spans.
const sh = L.farl / u.u_fold, ww = (sh * w) / S, wh = (sh * h) / S, unit = S / sh;
const dt = Math.min(ctx.dt, 0.1);

const restart = () => {
  s.run++;
  s.pal = u.u_palette >= 0 ? s.palettes[Math.round(u.u_palette)] : s.palettes[s.run % s.palettes.length];
  s.palKey = u.u_palette;
  L.n = 0; L.steps = 0;
  // one ring in the middle (main_ani.py: 40 vertices; a slightly larger radius so it reads at once), sometimes a few more around it
  const r = L.farl * 0.9;
  const extra = s.run === 0 ? 0 : Math.random() < 0.5 ? 0 : 1 + Math.floor(Math.random() * 3);
  addRing(L, 0, 0, r, 40);
  for (let k = 0; k < extra; k++) {
    const a = Math.random() * Math.PI * 2, d = (0.22 + Math.random() * 0.12) * Math.min(ww, wh);
    addRing(L, Math.cos(a) * d * (ww / Math.min(ww, wh)) * 0.8, Math.sin(a) * d, r, 40);
  }
  s.phase = "grow"; s.phaseT = 0; s.fadeT = 0;
};

// trail + fill targets follow the canvas size
const fmt = s.floatOK ? { internalFormat: gl.RGBA16F, format: gl.RGBA, type: gl.HALF_FLOAT, filter: gl.LINEAR }
  : { internalFormat: gl.RGBA8, format: gl.RGBA, type: gl.UNSIGNED_BYTE, filter: gl.LINEAR };
if (!s.trail) {
  s.trail = ctx.utils.createPingPong(w, h, fmt);
  s.fill = ctx.utils.createPingPong(w, h, fmt);
  s.clearTrail = true;
  restart();
  s.fadeT = 1;
} else if (ctx.resized || s.trail.width !== w || s.trail.height !== h) {
  s.trail.resize(w, h); s.fill.resize(w, h); s.clearTrail = true;
  // the frame is the wall: if the line no longer fits the new shape, start over
  let out = false;
  for (let i = 0; i < L.n && !out; i++) out = Math.abs(L.x[i]) > ww / 2 || Math.abs(L.y[i]) > wh / 2;
  if (out) { restart(); s.fadeT = 1; }
}
if (u.u_restart) restart();
if (s.palKey !== u.u_palette) { s.pal = u.u_palette >= 0 ? s.palettes[Math.round(u.u_palette)] : s.pal; s.palKey = u.u_palette; s.clearTrail = true; }

// click: plant a new seed ring where the pointer is
if (ctx.mouseDown && !s.wasDown && s.phase === "grow") {
  addRing(L, (ctx.mouse[0] - 0.5) * ww, (0.5 - ctx.mouse[1]) * wh, L.farl * 0.625, 40);
}
s.wasDown = ctx.mouseDown;

// --- grow: as many steps as fit in a few milliseconds (Speed scales the budget), so it starts fast
s.phaseT += dt;
let stepsDone = 0;
if (s.phase === "grow") {
  const t0 = performance.now(), budget = 7 * u.u_speed, maxSteps = Math.round(24 * u.u_speed);
  const x0 = -ww / 2, y0 = -wh / 2;
  while (stepsDone < maxSteps && performance.now() - t0 < budget) {
    optimize(L, x0, y0, ww, wh);
    spawn(L, u.u_growth * 0.001);
    stepsDone++;
  }
  // The original stops when a vertex reaches the boundary. Here the frame edge is a wall the line folds
  // against, and a run ends once the frame is about full (vertex count for this area) or after 45 s.
  const mx = ww / 2 - L.farl * 0.5, my = wh / 2 - L.farl * 0.5;
  for (let i = 0; i < L.n; i++) {
    if (L.x[i] > mx) L.x[i] = mx; else if (L.x[i] < -mx) L.x[i] = -mx;
    if (L.y[i] > my) L.y[i] = my; else if (L.y[i] < -my) L.y[i] = -my;
  }
  const full = Math.min(L.cap - 64, 26000 * ww * wh * (0.04 / L.farl) ** 2);
  if (L.n >= full || s.phaseT > 45) { s.phase = "hold"; s.phaseT = 0; }
} else if (s.phase === "hold" && s.phaseT > 3) restart();

// --- walk the rings: segments in order (t = position along the ring) and signed fans for the fill
const seg = s.segData, fan = s.fanData, vis = s.visited;
vis.fill(0, 0, L.n);
let ns = 0, nf = 0;
for (let v0 = 0; v0 < L.n; v0++) {
  if (vis[v0]) continue;
  let count = 0, v = v0;
  do { vis[v] = 1; count++; v = L.nx[v]; } while (v !== v0 && count <= L.n);
  let i = 0; v = v0;
  const fx = L.x[v0], fy = L.y[v0];
  do {
    const nv = L.nx[v];
    seg[ns * 5] = L.x[v]; seg[ns * 5 + 1] = L.y[v]; seg[ns * 5 + 2] = L.x[nv]; seg[ns * 5 + 3] = L.y[nv];
    seg[ns * 5 + 4] = i / count; ns++;
    if (v !== v0 && nv !== v0) {
      const sg = Math.sign((L.x[v] - fx) * (L.y[nv] - fy) - (L.y[v] - fy) * (L.x[nv] - fx));
      const o = nf * 9;
      fan[o] = fx; fan[o + 1] = fy; fan[o + 2] = sg; fan[o + 3] = L.x[v]; fan[o + 4] = L.y[v]; fan[o + 5] = sg;
      fan[o + 6] = L.x[nv]; fan[o + 7] = L.y[nv]; fan[o + 8] = sg; nf++;
    }
    i++; v = nv;
  } while (v !== v0 && i <= count);
}
gl.bindBuffer(gl.ARRAY_BUFFER, s.segBuf); gl.bufferSubData(gl.ARRAY_BUFFER, 0, seg, 0, ns * 5);
gl.bindBuffer(gl.ARRAY_BUFFER, s.fanBuf); gl.bufferSubData(gl.ARRAY_BUFFER, 0, fan, 0, nf * 9);

const pal = s.pal;
const palU = { u_pa: pal.a, u_pb: pal.b, u_pc: pal.c, u_pd: pal.d };
const common = { u_resolution: [w, h], u_center: [w / 2, h / 2], u_unit: unit };
const drawSegs = (width, alpha, mixSolid) => {
  gl.useProgram(s.segProg);
  ctx.utils.setUniforms(s.segProg, { ...common, ...palU, u_lw: width, u_alpha: alpha, u_solid: pal.solid, u_mix: mixSolid });
  gl.bindVertexArray(s.segVao);
  gl.drawArraysInstanced(gl.TRIANGLES, 0, 6, ns);
  gl.bindVertexArray(null);
};

// trails: earlier states of the line stay behind, fading only when a new run starts
const T = s.trail.read();
gl.bindFramebuffer(gl.FRAMEBUFFER, T.framebuffer); gl.viewport(0, 0, w, h);
if (s.clearTrail) { gl.clearColor(0, 0, 0, 0); gl.clear(gl.COLOR_BUFFER_BIT); s.clearTrail = false; }
gl.enable(gl.BLEND);
if (s.fadeT < 1) {
  // a new growth has started: the old trails fade out underneath it
  s.fadeT = Math.min(1, s.fadeT + dt / 1.5);
  gl.blendFunc(gl.ZERO, gl.SRC_COLOR);
  gl.useProgram(s.fadeProg);
  ctx.utils.drawFullscreen(s.fadeProg, { u_keep: s.fadeT >= 1 ? 0 : Math.pow(0.02, dt / 1.5) });
}
gl.blendFunc(gl.ONE, gl.ONE);
// a snapshot of the line every 0.3 s, so the trails read as growth rings
s.snapT = (s.snapT ?? 0) + dt;
if (s.phase === "grow" && s.snapT >= 0.3) { s.snapT = 0; drawSegs(Math.max(1, S / 1000), 0.22 * u.u_trail, 0); }

// fill: winding number of the rings
const F = s.fill.read();
gl.bindFramebuffer(gl.FRAMEBUFFER, F.framebuffer);
gl.clearColor(0, 0, 0, 0); gl.clear(gl.COLOR_BUFFER_BIT);
if (u.u_fillAmt > 0 && nf > 0) {
  gl.useProgram(s.fanProg);
  ctx.utils.setUniforms(s.fanProg, common);
  gl.bindVertexArray(s.fanVao);
  gl.drawArrays(gl.TRIANGLES, 0, nf * 3);
  gl.bindVertexArray(null);
}
gl.disable(gl.BLEND);

// compose, then the live line on top
gl.bindFramebuffer(gl.FRAMEBUFFER, null); gl.viewport(0, 0, w, h);
gl.useProgram(s.viewProg);
ctx.utils.bindTexture(s.viewProg, "u_trailTex", T.texture, 0);
ctx.utils.bindTexture(s.viewProg, "u_fillTex", F.texture, 1);
ctx.utils.drawFullscreen(s.viewProg, { ...palU, u_dark: pal.dark, u_fillAmt: u.u_fillAmt, u_trailAmt: 1, u_ground: pal.ground });
gl.enable(gl.BLEND); gl.blendFunc(gl.ONE, gl.ONE_MINUS_SRC_ALPHA);
drawSegs(Math.max(1.2, S / 420) * u.u_width, 0.95, pal.mix);
gl.disable(gl.BLEND);

ctx.publish("vertices", L.n);
ctx.publish("steps/frame", stepsDone);
ctx.publish("palette", pal.name);

script.cleanup:
const s = ctx.state, gl = ctx.gl;
for (const p of [s.segProg, s.fanProg, s.viewProg, s.fadeProg]) gl.deleteProgram(p);
gl.deleteBuffer(s.segBuf); gl.deleteBuffer(s.fanBuf);
gl.deleteVertexArray(s.segVao); gl.deleteVertexArray(s.fanVao);
